mapper.select:
SELECT ci.id, ci.case_code, ci.case_name, ci.case_type, ci.case_source, ci.respondent_name, ci.respondent_dept, ci.respondent_position, ci.classification_level_id, ci.status, ci.filing_date, ci.close_date, ci.brief_description, ci.handling_dept_id, ci.handling_user_id, d.dept_name AS handling_dept_name, u.real_name AS handling_user_name, cl.level_name AS classification_level_name, ci.create_time, ci.update_time FROM case_info ci LEFT JOIN sys_dept d ON ci.handling_dept_id = d.id LEFT JOIN sys_user u ON ci.handling_user_id = u.id LEFT JOIN sys_classification_level cl ON ci.classification_level_id = cl.id
AND ci.case_code LIKE CONCAT('%', #{caseCode}, '%')
AND ci.case_name LIKE CONCAT('%', #{caseName}, '%')
AND ci.case_type = #{caseType}
AND ci.status = #{status}
AND ci.respondent_name LIKE CONCAT('%', #{respondentName}, '%')
AND ci.handling_dept_id = #{handlingDeptId}
AND ci.filing_date >= #{startDate}
AND ci.filing_date <= #{endDate}
ORDER BY ci.create_time DESC
